// Puts the texts of the welcome and help screens into the plugin.
//
// The "What is new" note says what CHANGELOG.md says; the Help pane lists the
// tutorial's steps (docs/tutorial.md, "Contents") and what each command does
// (docs/guide.md, "All commands"). The plugin may not read files outside the
// vault, so the build copies those pieces into a small TypeScript module that
// the plugin bundles. That module is generated: it is kept in git so that the
// tests and the type check work without a build, and a test fails when it no
// longer says what the files say. Do not edit it by hand: change the files
// and run "npm run build" (or this script).

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

/** The sources, relative to the repository root. */
export const CHANGELOG_SOURCE = 'CHANGELOG.md';
export const GUIDE_SOURCE = 'docs/guide.md';
export const TUTORIAL_SOURCE = 'docs/tutorial.md';

/** The level-two headings whose sections are taken. */
export const GUIDE_SECTION = 'All commands';
export const TUTORIAL_SECTION = 'Contents';

/** The generated module, relative to the repository root. */
export const WELCOME_MODULE = 'src/features/welcome/bundledText.ts';

/**
 * Text with its line breaks as "\n", without a mark at its start, and with
 * exactly one line break at its end.
 *
 * @param {string} text
 * @returns {string}
 */
export function tidy(text) {
  const plain = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  return `${plain.replace(/\r\n?/g, '\n').replace(/\s+$/, '')}\n`;
}

/**
 * The section of a Markdown file under a level-two heading, without the
 * heading: up to the next level-two heading or the end.
 *
 * @param {string} markdown
 * @param {string} heading the heading's words, without the "## "
 * @returns {string}
 */
export function sectionOf(markdown, heading) {
  const lines = tidy(markdown).split('\n');
  const start = lines.findIndex((line) => line.trim() === `## ${heading}`);
  if (start < 0) throw new Error(`There is no heading "## ${heading}".`);
  let end = lines.length;
  for (let at = start + 1; at < lines.length; at++) {
    if (/^##\s/.test(lines[at] ?? '')) {
      end = at;
      break;
    }
  }
  return tidy(lines.slice(start + 1, end).join('\n').replace(/^\s+/, ''));
}

/**
 * The generated module for the three files.
 *
 * @param {{ changelog: string, guide: string, tutorial: string }} sources the files as they were read
 * @returns {string}
 */
export function welcomeModule(sources) {
  return [
    '// The texts of the welcome and help screens, as the plugin ships them.',
    '//',
    `// This file is generated by scripts/welcome.mjs from ${CHANGELOG_SOURCE}, the section`,
    `// "${GUIDE_SECTION}" of ${GUIDE_SOURCE} and the section "${TUTORIAL_SECTION}" of ${TUTORIAL_SOURCE}.`,
    '// Do not edit it by hand: change those files and run "npm run build".',
    '',
    '/** The whole changelog. */',
    `export const CHANGELOG_TEXT: string = ${JSON.stringify(tidy(sources.changelog))};`,
    '',
    '/** The table of every command and what it does. */',
    `export const COMMANDS_TEXT: string = ${JSON.stringify(sectionOf(sources.guide, GUIDE_SECTION))};`,
    '',
    "/** The tutorial's list of steps. */",
    `export const TUTORIAL_CONTENTS_TEXT: string = ${JSON.stringify(sectionOf(sources.tutorial, TUTORIAL_SECTION))};`,
    '',
  ].join('\n');
}

/**
 * Read the sources and give the module they make.
 *
 * @param {string} repoRoot absolute path of the plugin repository
 * @returns {string}
 */
export function readWelcomeModule(repoRoot) {
  const read = (/** @type {string} */ file) => readFileSync(path.join(repoRoot, file), 'utf8');
  return welcomeModule({ changelog: read(CHANGELOG_SOURCE), guide: read(GUIDE_SOURCE), tutorial: read(TUTORIAL_SOURCE) });
}

/**
 * Write the generated module, unless it already says exactly that.
 *
 * @param {string} repoRoot absolute path of the plugin repository
 * @returns {string} the path that was written
 */
export function writeWelcomeModule(repoRoot) {
  const output = path.join(repoRoot, WELCOME_MODULE);
  const text = readWelcomeModule(repoRoot);
  let current = null;
  try {
    current = readFileSync(output, 'utf8');
  } catch {
    current = null;
  }
  if (current !== text) writeFileSync(output, text, 'utf8');
  return output;
}

// Run by itself ("node scripts/welcome.mjs"), it writes the module.
if (process.argv[1] !== undefined && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeWelcomeModule(path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..'));
  console.log(`  ${WELCOME_MODULE}  written from ${CHANGELOG_SOURCE}, ${GUIDE_SOURCE} and ${TUTORIAL_SOURCE}`);
}
